1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { Job } from "@prisma/client";
4	import {
5	  runRealMigration,
6	  issueMigrationCertificates,
7	  migrationWorkDir,
8	  type MigrationStepResult,
9	  type ScanSnapshot,
10	} from "./migrate-real";
11	import { resolveCloudflareToken } from "../lib/cloudflare-oauth";
12	
13	/**
14	 * Real cross-provider transfer is OFF by default. It only runs when the operator
15	 * explicitly sets ENABLE_REAL_MIGRATION=1 (and never in the sandbox). Otherwise
16	 * the safe, progress-reporting SIMULATION below runs. The real engine
17	 * (worker/migrate-real.ts) is hardened against shell injection and never lets a
18	 * secret touch a command string. Enable it only after testing on a throwaway VM.
19	 */
20	const REAL_MIGRATION = process.env.ENABLE_REAL_MIGRATION === "1" && !SANDBOX;
21	
22	/**
23	 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
24	 * their new Nxeon server.
25	 *
26	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
27	 *   MIGRATE: runMigration,
28	 *
29	 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
30	 * handler trusts `payload.migrationId`.
31	 *
32	 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
33	 * mysqldump/pg_dump → import on target) is involved infra that has to be built
34	 * out carefully — see the TODO(real migration) block below. For now this runs a
35	 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
36	 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
37	 * connection to the customer's source box.
38	 *
39	 * On completion (DONE or FAILED) every stored source secret is CLEARED:
40	 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
41	 * therefore never retains usable credentials.
42	 */
43	
44	type MigratePayload = {
45	  migrationId?: string;
46	  /**
47	   * `"tls"` turns this job into the POST-DNS-CUTOVER certificate pass instead of
48	   * a migration: it re-runs the certificate ladder against the site
49	   * configuration the original run persisted, and copies nothing. See
50	   * `runPostCutoverTls` for why that is a separate phase rather than a separate
51	   * JobType (prisma/schema.prisma is frozen; `MIGRATE` already exists and is
52	   * already registered in worker/index.ts's handler map).
53	   */
54	  phase?: "tls";
55	};
56	type MigrationItems = {
57	  paths?: string[];
58	  // Legacy per-DB list (with encrypted password) — kept optional for old rows.
59	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
60	  // Passwordless lift-and-shift plan (extended TS shape carried through the
61	  // existing Migration.items Json column — no schema change).
62	  dbEngines?: string[];
63	  dockerVolumes?: string[];
64	  composeDirs?: string[];
65	  verifyPorts?: number[];
66	  hasContainers?: boolean;
67	  webServers?: string[];
68	  runtimes?: string[];
69	  scan?: ScanSnapshot;
70	  // Written back at completion: the honest per-step outcome summary.
71	  results?: MigrationStepResult[];
72	};
73	
74	const MAX_LOG_CHARS = 8000;
75	
76	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
77	
78	/** Append a timestamped line to a log tail, keeping it bounded. */
79	function appendLog(prev: string | null | undefined, line: string): string {
80	  const stamp = new Date().toISOString().slice(11, 19);
81	  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
82	  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
83	}
84	
85	async function loadMigration(job: Job) {
86	  const payload = (job.payload ?? {}) as MigratePayload;
87	  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
88	  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
89	  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
90	  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
91	  // the target server row separately. `dedicatedIp` AND `node` are both needed by
92	  // the real engine to compute the SSH connection target (connectionTarget() in
93	  // lib/sftp.ts falls back to the PRIMARY's own public IP when `node` is missing
94	  // — harmless while every server lives on the primary, wrong the moment a
95	  // migration's destination is a non-primary node).
96	  const server = await db.server.findUnique({
97	    where: { id: migration.serverId },
98	    include: { dedicatedIp: true, node: true },
99	  });
100	  return { ...migration, server };
101	}
102	
103	/**
104	 * Strip every source secret from a migration row. Called once the job finishes
105	 * (success or failure) so a completed migration never keeps usable credentials.
106	 */
107	async function clearSecrets(
108	  migrationId: string,
109	  items: MigrationItems,
110	  results?: MigrationStepResult[]
111	) {
112	  // Preserve every NON-secret field (so the wizard/summary keep working) while
113	  // stripping the only secret carried in items — each legacy DB's passEnc. The
114	  // source SSH password (sourcePasswordEnc column) is nulled separately.
115	  const scrubbed: MigrationItems = {
116	    ...items,
117	    databases: (items.databases ?? []).map((d) => ({
118	      engine: d.engine,
119	      name: d.name,
120	      user: d.user,
121	      // passEnc dropped entirely
122	    })),
123	    ...(results ? { results } : {}),
124	  };
125	  await db.migration.update({
126	    where: { id: migrationId },
127	    data: { sourcePasswordEnc: null, items: scrubbed as any },
128	  });
129	}
130	
131	async function report(
132	  migrationId: string,
133	  progress: number,
134	  step: string,
135	  logLine: string,
136	  logTail: string | null
137	): Promise<string> {
138	  const log = appendLog(logTail, logLine);
139	  await db.migration.update({
140	    where: { id: migrationId },
141	    data: { status: "RUNNING", progress, step, log },
142	  });
143	  return log;
144	}
145	
146	async function notify(userId: string, title: string, body?: string, href?: string) {
147	  try {
148	    await db.notification.create({ data: { userId, title, body, href } });
149	  } catch (e) {
150	    console.error("[migrate] notify failed", e);
151	  }
152	}
153	
154	/**
155	 * In-app alert to every operator (ADMIN) — the migration safety net. A run that
156	 * finishes COMPLETED_WITH_ISSUES is not a failure the customer should have to
157	 * debug over SSH; staff get pinged with the diagnosis and finish it. Mirrors the
158	 * admin-notify pattern used for feedback triage. Best-effort.
159	 */
160	async function notifyOperators(title: string, body: string, href: string) {
161	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
162	  if (!admins.length) return;
163	  await db.notification.createMany({
164	    data: admins.map((a) => ({ userId: a.id, title, body, href })),
165	  });
166	}
167	
168	// ---- TLS inputs: resolved HERE, on the Nxeon side --------------------------
169	/**
170	 * The three certificate inputs `runRealMigration` / `issueMigrationCertificates`
171	 * declare and that this caller used to drop on the floor.
172	 *
173	 * Real incident: the engine shipped a complete three-rung TLS ladder
174	 * (migrated certificate → DNS-01 wildcard via Cloudflare → HTTP-01 webroot) and
175	 * this call site passed only `{migration, target, items, report}`. The
176	 * consequences were invisible because every rung *degraded politely*:
177	 *
178	 *   - no `cloudflareToken`  ⇒ rung 3 could never fire, so every multi-tenant
179	 *     app was told "Connect Cloudflare in Settings" even when the customer had
180	 *     already completed the OAuth flow. A `*.domain` cert cannot be issued any
181	 *     other way (HTTP-01 cannot validate a wildcard), so those tenants were
182	 *     permanently stuck on a certificate warning.
183	 *   - no `acmeEmail`        ⇒ every certificate registered
184	 *     `--register-unsafely-without-email`, so Let's Encrypt has no address to
185	 *     send the 20/7/1-day expiry warnings to. That failure is silent for 60 days
186	 *     and then takes the site down.
187	 *   - no `knownDomains`     ⇒ hostnames the customer registered WITH US were
188	 *     excluded from the published set and from the certificate SANs.
189	 *
190	 * Everything is read from OUR database — never off the customer's box.
191	 * Resolution never throws: a missing/expired Cloudflare connection simply drops
192	 * the engine to a lower rung, exactly as it does for a customer who never
193	 * connected, and that is reported honestly in the run log.
194	 */
195	type MigrationTlsInputs = {
196	  cloudflareToken: string | null;
197	  acmeEmail: string | null;
198	  knownDomains: string[];
199	  /** One line for the run log, so the customer can see which rungs are available. */
200	  note: string;
201	};
202	
203	async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
204	  let cloudflareToken: string | null = null;
205	  let acmeEmail: string | null = null;
206	  const knownDomains: string[] = [];
207	  const notes: string[] = [];
208	
209	  try {
210	    const user = await db.user.findUnique({
211	      where: { id: userId },
212	      select: { id: true, email: true, cloudflareTokenEnc: true },
213	    });
214	    if (user) {
215	      // The account email is the ACME contact. This is what turns Let's
216	      // Encrypt's expiry warnings back on; without it a certificate that stops
217	      // renewing is only discovered by a visitor.
218	      acmeEmail = user.email ?? null;
219	      const resolved = await resolveCloudflareToken(user);
220	      if (resolved.token) {
221	        cloudflareToken = resolved.token;
222	        notes.push("your connected Cloudflare account is available, so wildcard certificates can be issued automatically (DNS-01)");
223	      } else {
224	        notes.push(
225	          "Cloudflare is not connected, so a wildcard certificate (needed when an app gives each tenant its own subdomain) cannot be issued automatically — connect it in Settings and we can finish that for you"
226	        );
227	      }
228	    }
229	  } catch (e) {
230	    // A DB hiccup here must never fail a migration — it only costs a rung.
231	    console.error("[migrate] could not resolve Cloudflare/ACME inputs", e);
232	    notes.push("we could not read your Cloudflare connection just now, so certificates were issued without it");
233	  }
234	
235	  try {
236	    const domains = await db.domain.findMany({
237	      where: { userId },
238	      select: { name: true },
239	      orderBy: { name: "asc" },
240	      take: 50,
241	    });
242	    for (const d of domains) if (d.name) knownDomains.push(d.name);
243	  } catch (e) {
244	    console.error("[migrate] could not load registered domains", e);
245	  }
246	
247	  return { cloudflareToken, acmeEmail, knownDomains, note: notes.join("; ") };
248	}
249	
250	/**
251	 * POST-DNS-CUTOVER certificate pass.
252	 *
253	 * HTTP-01 cannot validate a hostname that still resolves to the OLD server —
254	 * that is a property of the protocol, not a bug — so at migration time every
255	 * name whose DNS has not moved comes back as a named pending item. This is the
256	 * second half: run the same ladder again once the record is live.
257	 *
258	 * `issueMigrationCertificates` was written for exactly this and, until now, had
259	 * ZERO callers, so TLS was never retried after cutover and the customer's first
260	 * HTTPS visit was a certificate warning.
261	 *
262	 * Deliberate properties:
263	 *   - It copies NOTHING. It re-reads the `sites.json` the original run persisted
264	 *     on the target, walks the ladder, and reloads the vhost. A migration is
265	 *     never re-run by this path, so an accidental/duplicate enqueue cannot
266	 *     re-transfer a customer's data over the top of itself.
267	 *   - It is idempotent: certbot's `--keep-until-expiring` makes it a no-op once
268	 *     a certificate is in place, so it is safe to enqueue repeatedly.
269	 *   - It does NOT touch `Migration.status`. The terminal outcome belongs to the
270	 *     run that measured it; a certificate pass has not re-probed the sites and
271	 *     must not silently upgrade `COMPLETED_WITH_ISSUES` to `DONE`.
272	 *   - It never touches the SOURCE server.
273	 *
274	 * Enqueue it with:
275	 *   db.job.create({ data: { type: "MIGRATE", payload: { migrationId, phase: "tls" } } })
276	 */
277	async function runPostCutoverTls(
278	  migration: Awaited<ReturnType<typeof loadMigration>>,
279	  items: MigrationItems
280	): Promise<void> {
281	  const target = migration.server;
282	  const targetName = target ? target.label || target.hostname : "your server";
283	
284	  // Append-only log write: the migration row is already terminal and its status,
285	  // progress and step are the honest record of the run that produced them.
286	  let log = migration.log ?? null;
287	  const say = async (line: string) => {
288	    log = appendLog(log, line);
289	    await db.migration.update({ where: { id: migration.id }, data: { log } }).catch(() => {});
290	  };
291	
292	  if (!REAL_MIGRATION) {
293	    await say("HTTPS re-check skipped: real migration is not enabled on this platform, so no certificate was requested.");
294	    return;
295	  }
296	
297	  await say("Your DNS has moved — re-checking HTTPS and issuing any certificate that could not be issued before.");
298	  const tls = await resolveTlsInputs(migration.userId);
299	  if (tls.note) await say(`  ${tls.note}.`);
300	
301	  const res = await issueMigrationCertificates({
302	    target: target as any,
303	    migrationId: migration.id,
304	    extraDomains: tls.knownDomains,
305	    cloudflareToken: tls.cloudflareToken,
306	    acmeEmail: tls.acmeEmail,
307	    // Progress is meaningless for a post-cutover pass (the migration is over), so
308	    // the reporter is used purely as a log sink.
309	    report: async (_p, _s, line) => {
310	      await say(line);
311	    },
312	  });
313	
314	  if (res.error) {
315	    await say(`HTTPS re-check could not run: ${res.error}`);
316	    // A permanent condition — this run published no site configuration, so there
317	    // is nothing a later attempt could find. Settle it and stay silent: the
318	    // customer has no HTTPS problem to act on, because they have no published
319	    // sites. Notifying here would tell them about certificates for sites that do
320	    // not exist, once every retry, for a fortnight.
321	    if (res.permanent) {
322	      await db.migration
323	        .update({ where: { id: migration.id }, data: { items: { ...items, tlsSettled: true } as object } })
324	        .catch(() => {});
325	      return;
326	    }
327	    // Transient (SSH refused, target rebooting, certbot busy). Worth retrying —
328	    // but worth telling the customer only ONCE, not on every attempt.
329	    if (!(items as { tlsErrorNotified?: boolean }).tlsErrorNotified) {
330	      await db.migration
331	        .update({ where: { id: migration.id }, data: { items: { ...items, tlsErrorNotified: true } as object } })
332	        .catch(() => {});
333	      await notify(
334	        migration.userId,
335	        `Couldn't finish HTTPS on ${targetName}`,
336	        `${res.error} Your site keeps serving; only the certificate step is outstanding. We'll keep trying. Nothing on your old server was touched.`,
337	        "/dashboard/migrate"
338	      );
339	    }
340	    return;
341	  }
342	
343	  const secured = res.secured ?? [];
344	  const pending = res.pending ?? [];
345	  // Nothing outstanding — record it so `postCutoverTlsSweep` stops re-enqueuing
346	  // this migration. Written into `items` (an existing JSON column) rather than a
347	  // new schema field: it is a fact about this run and belongs with the run's data.
348	  if (!pending.length) {
349	    await db.migration
350	      .update({ where: { id: migration.id }, data: { items: { ...items, tlsSettled: true } as object } })
351	      .catch(() => {});
352	  }
353	  if (secured.length) {
354	    await say(`HTTPS is live for ${secured.slice(0, 8).join(", ")}${secured.length > 8 ? ` (+${secured.length - 8} more)` : ""}.`);
355	  }
356	  for (const p of pending.slice(0, 8)) await say(`  HTTPS still outstanding for ${p.domain}: ${p.why}. To finish: ${p.fix}`);
357	
358	  await notify(
359	    migration.userId,
360	    pending.length
361	      ? `HTTPS on ${targetName} — ${secured.length} secured, ${pending.length} still to finish`
362	      : `HTTPS is live on ${targetName}`,
363	    (secured.length ? `A valid certificate is now in place for ${secured.slice(0, 6).join(", ")}. ` : "") +
364	      (pending.length
365	        ? `Still outstanding: ${pending.slice(0, 4).map((p) => `${p.domain} — ${p.why}`).join(" | ")}. `
366	        : "") +
367	      // Said every time, because it is the customer's actual safety net and the
368	      // moment DNS has just moved is the moment they most need to know it.
369	      "Your old server was only ever read from — nothing on it was changed, so pointing DNS back to it is still a complete rollback.",
370	    "/dashboard/migrate"
371	  );
372	}
373	
374	// ---- Abandoned migrations: the credential promise, kept on the crash path ---
375	/**
376	 * How long a migration may sit unfinished with NO live job before it is declared
377	 * abandoned. Generous: a real lift-and-shift of a large box legitimately runs for
378	 * a long time, and while it does its job row is QUEUED or RUNNING, which exempts
379	 * it from this entirely.
380	 */
381	export const MIGRATION_ABANDON_MS = 3 * 60 * 60_000;
382	
383	export type AbandonedMigrationInput = {
384	  status: string;
385	  finishedAt: Date | null;
386	  createdAt: Date;
387	  /** Is there a MIGRATE job for this migration still QUEUED or RUNNING? */
388	  hasLiveJob: boolean;
389	  now: number;
390	  maxAgeMs?: number;
391	};
392	
393	/**
394	 * Is this migration abandoned — unfinished, with nothing left that could ever
395	 * finish it?
396	 *
397	 * WHY THIS EXISTS. Two documents promise the same thing in the same words:
398	 * `lib/actions-migrate.ts` ("They are CLEARED by the worker the moment the
399	 * migration finishes — success or failure — so a completed Migration row never
400	 * retains usable credentials") and this file's own header. Both are true for
401	 * every path that reaches `runMigration`'s try/catch. Neither is true for the
402	 * path where the worker never reaches it:
403	 *
404	 *   worker crash / restart  →  `reapStuckJobs` (worker/index.ts) re-QUEUEs the
405	 *   MIGRATE job  →  it crashes again  →  `attempts >= MAX_ATTEMPTS`  →  the job
406	 *   is marked FAILED and handed to `reconcileFailedJob`, which handles RESIZE and
407	 *   DISK_EXPAND and returns immediately for everything else.
408	 *
409	 * Nothing then touches the Migration row again. It keeps `status: "RUNNING"`
410	 * forever — the customer's wizard polls a progress bar that will never move — and
411	 * it keeps `sourcePasswordEnc`, which is the ROOT SSH PASSWORD OF ANOTHER
412	 * PROVIDER'S LIVE SERVER, encrypted at rest but retained indefinitely for a run
413	 * that ended hours ago. "Cleared when the run ends, success or failure" has to
414	 * include the failure mode where nothing was there to clear it.
415	 *
416	 * Pure so the rule is testable without a database, a worker or a clock.
417	 */
418	export function isAbandonedMigration(m: AbandonedMigrationInput): boolean {
419	  if (m.finishedAt) return false;
420	  if (m.status !== "PENDING" && m.status !== "RUNNING") return false;
421	  // Something can still finish it — leave it alone however long it takes.
422	  if (m.hasLiveJob) return false;
423	  return m.now - m.createdAt.getTime() >= (m.maxAgeMs ?? MIGRATION_ABANDON_MS);
424	}
425	
426	/** What an abandoned migration is told, in the customer's words. */
427	const ABANDONED_MIGRATION_ERROR =
428	  "This migration stopped before it finished — the transfer was interrupted and nothing was left running that could pick it up. " +
429	  "Nothing on your old server was changed at any point, so it is still serving exactly as it was. Start the migration again when you're ready.";
430	
431	/**
432	 * Settle every abandoned migration: mark it FAILED and CLEAR its stored source
433	 * credentials. See `isAbandonedMigration` for the crash path this closes.
434	 *
435	 * Returns how many it settled, so the caller can log a number it actually
436	 * counted rather than an assurance.
437	 */
438	export async function reapAbandonedMigrations(): Promise<number> {
439	  const rows = await db.migration.findMany({
440	    where: { finishedAt: null, status: { in: ["PENDING", "RUNNING"] } },
441	    select: { id: true, userId: true, status: true, createdAt: true, finishedAt: true, items: true, log: true },
442	    orderBy: { createdAt: "asc" },
443	    take: 100,
444	  });
445	  if (!rows.length) return 0;
446	
447	  const now = Date.now();
448	  let reaped = 0;
449	  for (const m of rows) {
450	    const live = await db.job.findFirst({
451	      where: {
452	        type: "MIGRATE",
453	        status: { in: ["QUEUED", "RUNNING"] },
454	        payload: { path: ["migrationId"], equals: m.id },
455	      },
456	      select: { id: true },
457	    });
458	    if (!isAbandonedMigration({ status: m.status, finishedAt: m.finishedAt, createdAt: m.createdAt, hasLiveJob: !!live, now })) {
459	      continue;
460	    }
461	    const items = (m.items ?? {}) as MigrationItems;
462	    try {
463	      await db.migration.update({
464	        where: { id: m.id },
465	        data: {
466	          status: "FAILED",
467	          step: "Stopped before finishing",
468	          lastError: ABANDONED_MIGRATION_ERROR,
469	          finishedAt: new Date(),
470	          log: appendLog(m.log, `ERROR: ${ABANDONED_MIGRATION_ERROR}`),
471	        },
472	      });
473	      // The whole point of the sweep. Runs even if the status write above threw,
474	      // because retaining the credential is the worse of the two failures.
475	    } finally {
476	      await clearSecrets(m.id, items).catch((e) =>
477	        console.error(`[migrate] could not clear secrets for abandoned migration ${m.id}:`, e)
478	      );
479	    }
480	    reaped++;
481	    await notify(
482	      m.userId,
483	      "Migration stopped before it finished",
484	      ABANDONED_MIGRATION_ERROR,
485	      "/dashboard/migrate"
486	    );
487	  }
488	  if (reaped) console.log(`[migrate] settled ${reaped} abandoned migration(s) and cleared their stored source credentials`);
489	  return reaped;
490	}
491	
492	/** How long after a migration finishes we keep watching for the DNS cutover. */
493	const TLS_WATCH_DAYS = 14;
494	/** Minimum gap between certificate attempts for one migration. */
495	const TLS_RETRY_MS = 6 * 60 * 60_000;
496	/**
497	 * The longest one certificate pass may occupy the serial worker. Generous enough
498	 * for SSH plus certbot on a slow box, short enough that an unreachable target
499	 * cannot hold up provisioning.
500	 */
501	const TLS_PASS_TIMEOUT_MS = 4 * 60_000;
502	
503	/**
504	 * Enqueue the post-cutover certificate pass for migrations whose DNS may have
505	 * moved since they finished.
506	 *
507	 * WHY THIS EXISTS. `runPostCutoverTls` was written for exactly this job and had
508	 * exactly one enqueue line — **inside a comment**. So it was dead code, and a
509	 * customer who migrated, then pointed their DNS a day later, never got the
510	 * certificate that could not be issued during the run: their first HTTPS visit
511	 * was a browser warning, forever.
512	 *
513	 * That was bad on its own. It became worse on 2026-07-26, when the migration
514	 * report's cutover instructions were rewritten to tell the customer, in plain
515	 * words, that "Nxeon issues the certificate automatically within about 30 minutes
516	 * of the change, and nothing else is needed." That sentence was false the moment
517	 * it shipped. `sslSweep` does NOT cover this case — it walks `db.sslCertificate`
518	 * rows, and a migration never writes one. A promise the product does not keep is
519	 * the same defect as a success this engine did not verify, so the promise is made
520	 * true here rather than walked back in the copy.
521	 *
522	 * Safe to run repeatedly by construction: the pass copies nothing, never touches
523	 * the source server, never rewrites `Migration.status`, and certbot's
524	 * `--keep-until-expiring` makes an already-certified domain a no-op.
525	 */
526	export async function postCutoverTlsSweep(): Promise<void> {
527	  // Settled here rather than in its own registered sweep because this function is
528	  // the migration subsystem's ONLY periodic entry point (worker/index.ts calls it
529	  // every 30 minutes) and an unfinished migration holding a source root password
530	  // must not wait for a new registration to be plumbed in. It is wrapped so a
531	  // failure here can never stop the certificate pass that follows.
532	  await reapAbandonedMigrations().catch((e) => console.error("[migrate] abandoned-migration sweep failed:", e));
533	
534	  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);
535	  const runningServerIds = (
536	    await db.server.findMany({ where: { status: "RUNNING" }, select: { id: true } })
537	  ).map((s) => s.id);
538	  if (!runningServerIds.length) return;
539	
540	  const candidates = await db.migration.findMany({
541	    where: {
542	      status: { in: ["DONE", "COMPLETED_WITH_ISSUES"] },
543	      finishedAt: { gte: since },
544	      // SSH is the first thing this pass does. A server that is not running
545	      // cannot answer, and the attempt would occupy the strictly-serial worker
546	      // until the connection times out. `Migration.serverId` is a bare column
547	      // with no Prisma relation, so the running set is resolved separately.
548	      serverId: { in: runningServerIds },
549	    },
550	    select: { id: true, items: true, serverId: true },
551	    orderBy: { finishedAt: "desc" },
552	    take: 50,
553	  });
554	
555	  // ONE pass per target server, not per migration. A customer who retried a
556	  // migration three times has three rows pointing at the same box; certifying it
557	  // once certifies it for all of them, and the first live run queued four
558	  // redundant SSH sessions for a single server. Newest first, since that run's
559	  // published site config is the one on disk.
560	  const seenServers = new Set<string>();
561	
562	  for (const m of candidates) {
563	    // Already fully certified — a previous pass found nothing outstanding.
564	    if ((m.items as { tlsSettled?: boolean } | null)?.tlsSettled) continue;
565	    if (seenServers.has(m.serverId)) continue;
566	    seenServers.add(m.serverId);
567	
568	    // Don't stack attempts. A job still queued, or one tried recently, means the
569	    // answer is already on its way; certbot rate limits are real and shared.
570	    const recent = await db.job.findFirst({
571	      where: {
572	        type: "MIGRATE",
573	        createdAt: { gte: new Date(Date.now() - TLS_RETRY_MS) },
574	        payload: { path: ["migrationId"], equals: m.id },
575	      },
576	      select: { id: true },
577	    });
578	    if (recent) continue;
579	
580	    await db.job
581	      .create({ data: { type: "MIGRATE", payload: { migrationId: m.id, phase: "tls" } } })
582	      .catch((e) => console.error(`[migrate] could not enqueue TLS pass for ${m.id}:`, e));
583	  }
584	}
