586	export async function runMigration(job: Job): Promise<void> {
587	  const migration = await loadMigration(job);
588	  const items = (migration.items ?? {}) as MigrationItems;
589	  const paths = items.paths ?? [];
590	  const target = migration.server;
591	  const targetName = target ? target.label || target.hostname : "your server";
592	
593	  // The post-cutover certificate pass shares this handler (and therefore the
594	  // already-registered MIGRATE JobType) but is NOT a migration: it copies
595	  // nothing and must never fall through into the transfer below.
596	  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
597	    try {
598	      // HARD CEILING. This worker is strictly serial: whatever is in this
599	      // function is the only thing the platform is doing. The pass opens SSH to a
600	      // customer's box and runs certbot, and on the sweep's first live run a
601	      // single unresponsive target left the job RUNNING through two reap cycles
602	      // — with a new customer's provisioning job queued behind it. A background
603	      // nicety must never be able to stall the queue that provisions servers.
604	      await Promise.race([
605	        runPostCutoverTls(migration, items),
606	        new Promise<never>((_, reject) =>
607	          setTimeout(() => reject(new Error("post-cutover TLS pass exceeded its time budget")), TLS_PASS_TIMEOUT_MS)
608	        ),
609	      ]);
610	    } catch (e) {
611	      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
612	      // Swallowed on purpose: a failed certificate retry must not mark the
613	      // customer's finished migration as failed, and must not make the job loop
614	      // retry a phase that will keep failing for the same reason. The sweep will
615	      // come back to it on its own schedule.
616	    }
617	    return;
618	  }
619	
620	  // Fresh start (also lets a retried job re-enter cleanly).
621	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
622	  await db.migration.update({
623	    where: { id: migration.id },
624	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
625	  });
626	
627	  // Shared progress reporter: threads the bounded log tail through each update so
628	  // both the real engine and the simulation write to the same Migration row.
629	  const reportStep = async (progress: number, step: string, line: string) => {
630	    log = await report(migration.id, progress, step, line, log);
631	  };
632	
633	  try {
634	    if (REAL_MIGRATION) {
635	      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
636	      // Resolve the TLS inputs BEFORE the engine starts. These three arguments
637	      // are what make the certificate ladder reachable at all — see
638	      // resolveTlsInputs for the failure each dropped argument caused.
639	      const tls = await resolveTlsInputs(migration.userId);
640	      if (tls.note) await reportStep(5, "Starting", `HTTPS: ${tls.note}.`);
641	
642	      const summary = await runRealMigration({
643	        migration: {
644	          id: migration.id,
645	          sourceHost: migration.sourceHost,
646	          sourcePort: migration.sourcePort,
647	          sourceUser: migration.sourceUser,
648	          sourcePasswordEnc: migration.sourcePasswordEnc,
649	        },
650	        target: target as any,
651	        items,
652	        report: reportStep,
653	        // Rung 3 of the certificate ladder: a wildcard (`*.domain`) can ONLY be
654	        // issued with a DNS-01 challenge, so a multi-tenant app is stuck on a
655	        // certificate warning without this token.
656	        cloudflareToken: tls.cloudflareToken,
657	        // Without this every cert is `--register-unsafely-without-email` and
658	        // Let's Encrypt has nobody to warn before it expires.
659	        acmeEmail: tls.acmeEmail,
660	        // Hostnames the customer registered with us, folded into the published
661	        // set and the certificate SANs when they belong to a served site.
662	        knownDomains: tls.knownDomains,
663	      });
664	
665	      // The engine returns an HONEST outcome. A run that executed every step but
666	      // left a source domain dark — or a migrated unit crash-looping — is NOT a
667	      // success, and must never be written back as one.
668	      //
669	      // This line is why the 2026-07-25 migration reported "Completed" while the
670	      // customer's site served a certificate warning and then Apache's default
671	      // page: the status was hardcoded, so no amount of verification downstream
672	      // could change what the customer was told. `COMPLETED_WITH_ISSUES` is
673	      // terminal (MigrationWizard treats it as an end state) but visibly distinct.
674	      const clean = summary.outcome === "COMPLETED";
675	      const unserved = summary.unservedDomains ?? [];
676	      const cust = await db.user
677	        .findUnique({ where: { id: migration.userId }, select: { email: true } })
678	        .catch(() => null);
679	      const customerLabel = cust?.email ?? migration.userId;
680	      await db.migration.update({
681	        where: { id: migration.id },
682	        data: {
683	          status: clean ? "DONE" : "COMPLETED_WITH_ISSUES",
684	          progress: 100,
685	          step: clean ? "Completed" : "Finished — some sites need attention",
686	          finishedAt: new Date(),
687	        },
688	      });
689	      // Persist the honest step-by-step summary (secret-free) into items.results.
690	      await clearSecrets(migration.id, items, summary.results);
691	
692	      const workDir = migrationWorkDir(migration.id);
693	      const running = summary.verifiedRunning.length;
694	      const manual = summary.needsAttention.length;
695	      const tail =
696	        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. ` +
697	        `Your old server is untouched — if anything looks wrong, point DNS back to it while we sort this out.`;
698	      // Lead with the bad news when there is bad news. Burying dark domains under
699	      // a "completed" headline is what cost the customer a working site.
700	      const body = clean
701	        ? `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
702	          `${manual} copied that may need a manual step. ` +
703	          (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
704	          tail
705	        : `Lift-and-shift onto ${targetName} finished, but it is NOT fully live yet. ` +
706	          (unserved.length
707	            ? `These site(s) are not serving on the new server: ${unserved.slice(0, 8).join(", ")}${unserved.length > 8 ? ` (+${unserved.length - 8} more)` : ""}. `
708	            : "") +
709	          `${(summary.outcomeReasons ?? []).join("; ")}. ` +
710	          `${running} item(s) verified running. ` +
711	          tail;
712	      await notify(
713	        migration.userId,
714	        clean
715	          ? `Migration to ${targetName} completed`
716	          : `Migration to ${targetName} finished — ${unserved.length || "some"} site(s) need attention`,
717	        body,
718	        "/dashboard/migrate"
719	      );
720	      // Operator safety net: a migration that did not fully go live is a support
721	      // event, not a silent dead end. Ping staff with the diagnosis so someone
722	      // finishes it — the customer must never be left needing an engineer with
723	      // SSH to their box (the whole reason process-capture + this alert exist).
724	      if (!clean) {
725	        await notifyOperators(
726	          `Migration needs attention — ${targetName}`,
727	          `${customerLabel} · onto ${targetName}. ` +
728	            (unserved.length ? `Not serving: ${unserved.slice(0, 10).join(", ")}${unserved.length > 10 ? ` (+${unserved.length - 10})` : ""}. ` : "") +
729	            `${(summary.outcomeReasons ?? []).slice(0, 3).join("; ")}.`,
730	          `/admin/migrations`
731	        ).catch((e) => console.error("[migrate] operator alert failed", e));
732	      }
733	      return;
734	    }
735	
736	    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
737	    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
738	    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
739	    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
740	    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
741	    const composeDirs = items.composeDirs ?? [];
742	    const webServers = items.webServers ?? [];
743	    const runtimes = items.runtimes ?? [];
744	    const verifyPorts = items.verifyPorts ?? [];
745	    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
746	    const simResults: MigrationStepResult[] = [];
747	
748	    await reportStep(6, "Connecting…", `Connecting to your Nxeon server (${targetName}) to prepare the lift-and-shift.`);
749	    await sleep(SANDBOX ? 500 : 1000);
750	    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
751	    await sleep(SANDBOX ? 400 : 800);
752	
753	    // Prerequisites stage.
754	    const prereqLabels: string[] = [];
755	    if (dbEngines.includes("mysql")) prereqLabels.push("MySQL/MariaDB server");
756	    if (dbEngines.includes("postgres")) prereqLabels.push("PostgreSQL server");
757	    if (hasContainers) prereqLabels.push("Docker Engine + compose");
758	    for (const w of webServers) prereqLabels.push(w === "nginx" ? "nginx" : "Apache");
759	    for (const rt of runtimes) prereqLabels.push(rt === "nodejs" ? "Node.js" : "Python 3 + pip");
760	    if (prereqLabels.length) {
761	      await reportStep(18, "Installing prerequisites…", `Installing on ${targetName}: ${prereqLabels.join(", ")}.`);
762	      for (const lbl of prereqLabels) {
763	        await sleep(SANDBOX ? 200 : 400);
764	        await reportStep(20, "Installing prerequisites…", `  ${lbl}: installed.`);
765	        simResults.push({ step: `Install ${lbl}`, status: "running", detail: "installed" });
766	      }
767	    }
768	
769	    // Files stage — same-path copy.
770	    await reportStep(30, "Copying files…", paths.length ? `Copying ${paths.length} path(s) to the same locations on ${targetName}.` : "No file paths selected — skipping file copy.");
771	    for (const p of paths) {
772	      await sleep(SANDBOX ? 200 : 400);
773	      await reportStep(40, "Copying files…", `  rsync ${p} → ${p}`);
774	    }
775	    if (paths.length) simResults.push({ step: `Copy ${paths.length} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths" });
776	
777	    // Databases — dump via source root LOCAL auth (no password), import on target.
778	    for (const eng of dbEngines) {
779	      await sleep(SANDBOX ? 300 : 600);
780	      if (eng === "mysql") {
781	        await reportStep(62, "Migrating databases…", "  mysqldump --all-databases via source root socket (no password) → mysql < dump on target.");
782	        simResults.push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported" });
783	      } else {
784	        await reportStep(64, "Migrating databases…", "  sudo -u postgres pg_dumpall via peer auth → psql -f on target.");
785	        simResults.push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported" });
786	      }
787	    }
788	
789	    // Docker compose bring-up.
790	    for (const dir of composeDirs) {
791	      await sleep(SANDBOX ? 250 : 500);
792	      await reportStep(76, "Starting containers…", `  cd ${dir} && docker compose up -d`);
793	      simResults.push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
794	    }
795	
796	    // Verification.
797	    await reportStep(92, "Verifying…", "Checking databases, containers and listening ports on the new server.");
798	    await sleep(SANDBOX ? 400 : 800);
799	    if (dbEngines.includes("mysql")) simResults.push({ step: "MySQL/MariaDB engine", status: "running", detail: "engine is active on the target" });
800	    if (dbEngines.includes("postgres")) simResults.push({ step: "PostgreSQL engine", status: "running", detail: "engine is active on the target" });
801	    if (hasContainers) {
802	      await reportStep(94, "Verifying…", `  docker ps shows ${composeDirs.length || 1} running container(s).`);
803	      simResults.push({ step: "Docker containers", status: "running", detail: `${composeDirs.length || 1} container(s) running` });
804	    }
805	    if (verifyPorts.length) {
806	      await reportStep(95, "Verifying…", `  ports up: ${verifyPorts.join(", ")}.`);
807	      simResults.push({ step: "Listening ports", status: "running", detail: `now listening: ${verifyPorts.join(", ")}` });
808	    }
809	
810	    const simRunning = simResults.filter((r) => r.status === "running").length;
811	    const simManual = simResults.filter((r) => r.status === "copied" || r.status === "failed").length;
812	    await reportStep(98, "Finalising…", `Migrated & running (verified): ${simRunning}. Copied — may need a manual step: ${simManual}.`);
