815	    await db.migration.update({
816	      where: { id: migration.id },
817	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
818	    });
819	    // Security: drop all source credentials now that the job is done; persist summary.
820	    await clearSecrets(migration.id, items, simResults);
821	
822	    await notify(
823	      migration.userId,
824	      `Migration to ${targetName} completed`,
825	      `Lift-and-shift onto ${targetName} finished: ${simRunning} item(s) migrated & running, ${simManual} copied. Point your DNS at the new server when ready.`,
826	      "/dashboard/migrate"
827	    );
828	  } catch (e: any) {
829	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
830	    console.error(`[migrate] migration ${migration.id} failed:`, e);
831	    log = appendLog(log, `ERROR: ${lastError}`);
832	    await db.migration
833	      .update({
834	        where: { id: migration.id },
835	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
836	      })
837	      .catch(() => {});
838	    // Security: clear the stored source password/DB secrets even on failure.
839	    await clearSecrets(migration.id, items).catch(() => {});
840	    await notify(
841	      migration.userId,
842	      `Migration to ${targetName} failed`,
843	      lastError,
844	      "/dashboard/migrate"
