1	import "server-only";
2	import { db } from "@/lib/db";
3	import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
4	import { geoLocateIp } from "@/lib/geo-ip";
5	import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
6	import { FREEMC_GAME_TYPES, FREEMC_GAME_MODES } from "@/lib/free-minecraft-control";
7	import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
8	import { connectAddress } from "@/lib/nx/connect-address";
9	import { gamePlanSpecs, specLine } from "@/lib/nx/plan-specs";
10	import { renewalCharge } from "@/lib/renewal-charge";
11	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
12	import { extraDiskPerGbCents } from "@/lib/disk-expand";
13	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
14	import { annualDiscountPct } from "@/lib/annual-discount";
15	import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
16	import { taxContextForUser } from "@/lib/tax";
17	// THE renewal-price formula for shared hosting — worker/product-renewals.ts's
18	// sweep charges through this same function, so the number shown here is the
19	// number that will actually be charged. See hostingRenewalPrice's own comment.
20	import {
21	  hostingRenewalPrice,
22	  emailMonthlyBaseCents,
23	  frozenProductAnnualPct,
24	  productTermRenewalCents,
25	  subscriptionTermMonths,
26	} from "@/lib/product-billing";
27	
28	/**
29	 * One customer's whole estate, normalised into a single list.
30	 *
31	 * The four products live in genuinely different tables — a VPS and a game
32	 * server are both `Server` rows told apart by `gamePlanId`, shared hosting is
33	 * a `HostingAccount`, and the free Minecraft tier is its own
34	 * `FreeMinecraftServer` — so this is the one place that flattens them into a
35	 * shape a single list can render. Everything below is read from the record;
36	 * nothing is inferred where the data doesn't exist (hosting has no region
37	 * column, so its location is geo-resolved from the node's real public IP the
38	 * same way the primary node's location was confirmed, and is left blank when
39	 * that lookup can't answer).
40	 */
41	export type ServiceKind = "vps" | "game" | "hosting" | "free" | "domain" | "email";
42	
43	/** The five buckets the page's stat row and status pills speak in. */
44	export type ServiceStatus = "running" | "pending" | "stopped" | "suspended" | "error" | "cancelled";
45	
46	export type ServiceRow = {
47	  id: string;
48	  kind: ServiceKind;
49	  /** What the customer named it (or the domain, for hosting). */
50	  name: string;
51	  /** Where "Manage" goes. */
52	  href: string;
53	  typeLabel: string;
54	  /** The address a customer actually connects on. See `connectAddress`. */
55	  address: string | null;
56	  /** What that address IS, so the row can label it rather than guess. */
57	  addressLabel: "IP address" | "Connect" | "Website" | null;
58	  /** Second line under the name — plan/specs. */
59	  specs: string | null;
60	  status: ServiceStatus;
61	  statusLabel: string;
62	  location: { label: string; country: string } | null;
63	  renewalIso: string | null;
64	  /** Per-term price in cents; null when nothing is charged (free tier). */
65	  renewalCents: number | null;
66	  /** Billing term in months, so "/mo" vs "/yr" is honest. */
67	  termMonths: number;
68	  /** Game family id, for the box-art thumbnail. */
69	  gameFamily: string | null;
70	  /** Hosting only — the site to preview. */
71	  domain: string | null;
72	  createdAtIso: string;
73	
74	  /* ── card preview art ───────────────────────────────────────────────────
75	     Every card leads with a picture. Where it comes from depends on the
76	     product, and the rule is the same one the brief sets out: show the real
77	     thing if there is one, otherwise the stock plate for that product. */
78	
79	  /** The image the card leads with. Never null — there is always a fallback. */
80	  previewSrc: string;
81	  /** Which of the three sources `previewSrc` came from — the card badges it. */
82	  previewSource: "game-art" | "customer" | "stock";
83	  /**
84	   * Hosting only: the live site can be framed over the stock plate, so a plan
85	   * that is actually serving something shows THAT instead of the plate. There
86	   * is no screenshot service behind this — it is the customer's own site or
87	   * the plate, never a stand-in picture of some other website.
88	   */
89	  siteToFrame: string | null;
90	  /** VPS rows let the customer replace the stock plate with their own image. */
91	  canSetPreview: boolean;
92	  /**
93	   * VPS only: what it is actually running. Every VPS on the stock plate would
94	   * otherwise be the same picture, and the OS is the one thing that genuinely
95	   * tells them apart at a glance.
96	   */
97	  os: { family: string; name: string } | null;
98	};
99	
100	/** Tolerant status mapper: every product spells its states differently, and a
101	 *  new value should degrade to something sane rather than crash a list. */
102	function normalizeStatus(raw: string): { status: ServiceStatus; label: string } {
103	  const s = (raw ?? "").toUpperCase();
104	  if (["RUNNING", "ACTIVE", "ONLINE"].includes(s)) return { status: "running", label: "Running" };
105	  // The free tier's container states: READY means the container exists —
106	  // mc-router owns whether it is awake right now, and this list deliberately
107	  // doesn't claim to know that, so it says Ready rather than Running.
108	  if (s === "READY") return { status: "running", label: "Ready" };
109	  if (["PENDING", "PROVISIONING", "CREATING", "REINSTALLING", "STARTING"].includes(s)) {
110	    return { status: "pending", label: s === "REINSTALLING" ? "Reinstalling" : "Pending" };
111	  }
112	  if (["STOPPED", "SLEEPING", "OFFLINE"].includes(s)) {
113	    return { status: "stopped", label: s === "SLEEPING" ? "Asleep" : "Stopped" };
114	  }
115	  if (["SUSPENDED"].includes(s)) return { status: "suspended", label: "Suspended" };
116	  // Domain-only inbound-transfer states (DomainStatus) — without these two, the
117	  // fallback below stringifies "TRANSFER_PENDING" into "Transfer_pending".
118	  if (s === "TRANSFER_PENDING") return { status: "pending", label: "Transferring" };
119	  if (s === "TRANSFER_FAILED") return { status: "error", label: "Transfer failed" };
120	  if (["DELETING", "DELETED", "CANCELLED", "CANCELED", "TERMINATED", "EXPIRED"].includes(s)) {
121	    return { status: "cancelled", label: s === "DELETING" ? "Deleting" : "Cancelled" };
122	  }
123	  if (["ERROR", "FAILED"].includes(s)) return { status: "error", label: "Failed" };
124	  return { status: "pending", label: raw ? raw.charAt(0) + raw.slice(1).toLowerCase() : "Unknown" };
125	}
126	
127	function regionLocation(region: string | null | undefined) {
128	  if (!region) return null;
129	  const label = REGION_LABELS[region];
130	  if (!label) return null;
131	  return { label, country: REGION_COUNTRY[region] ?? "" };
132	}
133	
134	
135	
136	/** Stock plates, for a service with nothing of its own to show yet. */
137	const STOCK_PREVIEW = {
138	  vps: "/nx/preview/vps.webp",
139	  hosting: "/nx/preview/hosting.webp",
140	  // Neither product has its own wide 16:4 rack plate yet — domains reuse the
141	  // real hero art from /dashboard/domains rather than a stretched icon; email
142	  // has no dedicated wide art at all, so it falls back to its own service mark.
143	  domain: "/nx/hero-domains-globe.webp",
144	  email: "/nx/svc/email.webp",
145	} as const;
146	
147	/** Landscape key art for a game family, which every family in the catalogue has. */
148	function gameHeroArt(family: string | null): string | null {
149	  const slug = family ? GAME_ART_SLUG[family as GameFamily]?.hero : null;
150	  return slug ? `/games/art/${slug}_hero.jpg` : null;
151	}
152	
153	/**
154	 * Where a Server row's card image comes from, in priority order: the image the
155	 * customer set, then the game's own key art, then the stock rack plate. The
156	 * `v` stamp is the preview's updatedAt, so replacing an image busts the cache
157	 * without making the route itself uncacheable.
158	 */
159	function serverPreview(
160	  id: string, isGame: boolean, family: string | null, previewStamp: Date | null,
161	): Pick<ServiceRow, "previewSrc" | "previewSource" | "siteToFrame" | "canSetPreview"> {
162	  if (previewStamp) {
163	    return {
164	      previewSrc: `/api/services/preview/${id}?v=${previewStamp.getTime()}`,
165	      previewSource: "customer",
166	      siteToFrame: null,
167	      canSetPreview: true,
168	    };
169	  }
170	  const art = isGame ? gameHeroArt(family) : null;
171	  return {
172	    previewSrc: art ?? STOCK_PREVIEW.vps,
173	    previewSource: art ? "game-art" : "stock",
174	    siteToFrame: null,
175	    // Game servers lead with their own key art, which is better than anything a
176	    // customer would upload — the swap is offered on VPS rows only.
177	    canSetPreview: !isGame,
178	  };
179	}
180	
181	
182	export async function listServices(userId: string): Promise<ServiceRow[]> {
183	  const user = await db.user.findUnique({ where: { id: userId } });
184	  if (!user) return [];
185	
186	  // The play-subdomain base is an admin SETTING shared by free and paid game
187	  // servers, not a constant — reading it keeps the connect address honest if
188	  // the owner ever moves it off play.nxeon.cloud.
189	  const [servers, hosting, freeMc, domains, emailSubs, gameBase] = await Promise.all([
190	    db.server.findMany({
191	      // NxCloud instances are backed by a Server but sold as their own product,
192	      // so they stay out of this list exactly as they do on /dashboard/servers.
193	      where: { userId, nxcloudInstance: { is: null } },
194	      include: {
195	        plan: true,
196	        gamePlan: true,
197	        osTemplate: true,
198	        // `dedicatedIp` is not decoration here — renewalCharge bills it.
199	        dedicatedIp: { select: { address: true } },
200	        node: { select: { region: true, publicIp: true } },
201	        portForwards: { select: { publicPort: true, guestPort: true } },
202	        // Only the stamp — the bytes are served by their own route, and must
203	        // never be dragged into a list query.
204	        preview: { select: { updatedAt: true } },
205	      },
206	      orderBy: { createdAt: "desc" },
207	    }),
208	    db.hostingAccount.findMany({
209	      where: { userId },
210	      include: { plan: true, node: { select: { publicIp: true, name: true } } },
211	      orderBy: { createdAt: "desc" },
212	    }),
213	    db.freeMinecraftServer.findUnique({ where: { userId } }),
214	    // Only a domain that is actually registered and live is a "service" the
215	    // customer holds today — a failed registration, an expired name or a
216	    // transfer that never completed isn't something to renew or manage here.
217	    // Matches the "real, owned, currently active" filter app/dashboard/domains
218	    // uses for its own active-count tile.
219	    db.domain.findMany({
220	      where: { userId, status: "ACTIVE" },
221	      orderBy: { createdAt: "desc" },
222	    }),
223	    // Same "not cancelled" filter app/dashboard/email/page.tsx lists against —
224	    // a suspended (unpaid) mailbox is still a service to show and fix, only a
225	    // cancelled one is gone.
226	    db.emailSubscription.findMany({
227	      where: { userId, status: { not: "CANCELLED" } },
228	      include: { emailPlan: true },
229	      orderBy: { createdAt: "desc" },
230	    }),
231	    gameSubdomainBase(),
232	  ]);
233	
234	  /* What a server ACTUALLY renews at.
235	   *
236	   * `plan.priceCents` is not that number: it ignores the term (an annual server
237	   * renews at 12x less the frozen annual discount), it ignores every add-on the
238	   * customer really is billed for each cycle (dedicated IP, extra root disk,
239	   * paid backup retention), and for a game server it is the wrong plan
240	   * entirely — a game row carries BOTH a base planId and a gamePlanId and is
241	   * sold at the game plan's flat price. lib/renewal-quote.ts records what
242	   * happened the last two times someone wrote that second formula. So this
243	   * prices through `renewalCharge`, the same function worker/billing.ts, the
244	   * saved-card path and the Renew now button all CHARGE through. */
245	  const paid = servers.filter((s) => !s.isFree);
246	  const taxRatePercent = (await taxContextForUser(user)).ratePercent;
247	  // Hosting's renewal price needs `extraDiskPerGbCents`/`annualDiscountPct`, and
248	  // email's needs `annualDiscountPct` too (see `hostingRenewalPrice` below and
249	  // the email renewal calc further down) — so this can't stay gated on paid VPS
250	  // servers alone, or a customer with only hosting/email gets the same
251	  // DEFAULT_ANNUAL_DISCOUNT_PCT fallback a brand-new install would.
252	  const prices = paid.length > 0 || hosting.length > 0 || emailSubs.length > 0
253	    ? {
254	        ipMonthlyCents: await dedicatedIpMonthlyCents(),
255	        extraDiskPerGbCents: await extraDiskPerGbCents(),
256	        backupPlusCents: await backupPlusMonthlyCents(),
257	        annualDiscountPct: await annualDiscountPct(),
258	        taxRatePercent,
259	      }
260	    : {
261	        ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0,
262	        annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent,
263	      };
264	
265	  const rows: ServiceRow[] = [];
266	
267	  for (const s of servers) {
268	    const isGame = s.gamePlanId !== null;
269	    const st = normalizeStatus(s.status);
270	    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? null;
271	    const gameName = family ? GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family : null;
272	    const charge = renewalCharge(s, prices);
273	    rows.push({
274	      id: s.id,
275	      kind: isGame ? "game" : "vps",
276	      name: s.label || s.hostname,
277	      href: `/dashboard/servers/${s.id}`,
278	      typeLabel: isGame ? gameName ?? "Game Server" : "VPS Server",
279	      ...connectAddress(s, gameBase),
280	      specs: isGame
281	        ? gamePlanSpecs(s.gamePlan?.name, gameName, s.gamePlan?.slots)
282	        : s.plan
283	          ? specLine(s.plan.cpuCores, s.plan.ramMB, s.plan.diskGB, s.plan.storageTier)
284	          : null,
285	      status: st.status,
286	      statusLabel: st.label,
287	      location: regionLocation(s.node?.region),
288	      renewalIso: s.expiresAt ? s.expiresAt.toISOString() : null,
289	      renewalCents: s.isFree ? null : charge.totalCents,
290	      termMonths: s.isFree ? 1 : charge.months,
291	      gameFamily: isGame ? family : null,
292	      domain: null,
293	      createdAtIso: s.createdAt.toISOString(),
294	      ...serverPreview(s.id, isGame, family, s.preview?.updatedAt ?? null),
295	      os: !isGame && s.osTemplate
296	        ? {
297	            family: s.osTemplate.logo || s.osTemplate.family,
298	            // `name` is often already the full "Ubuntu 24.04 LTS", so appending
299	            // `version` unconditionally produced "Ubuntu 24.04 LTS 24.04".
300	            name: s.osTemplate.version && !s.osTemplate.name.includes(s.osTemplate.version)
301	              ? `${s.osTemplate.name} ${s.osTemplate.version}`
302	              : s.osTemplate.name,
303	          }
304	        : null,
305	    });
306	  }
307	
308	  for (const h of hosting) {
309	    const st = normalizeStatus(h.status);
310	    // No region column on HostingNode — resolve the node's real public IP
311	    // instead of inventing a city, and leave it blank if that can't answer.
312	    const geo = geoLocateIp(h.node?.publicIp ?? null);
313	    rows.push({
314	      id: h.id,
315	      kind: "hosting",
316	      name: h.primaryDomain,
317	      href: `/dashboard/hosting/${h.id}`,
318	      typeLabel: "Shared Hosting",
319	      // The name IS the domain here, so repeating it as an address would just
320	      // print the same string twice in the same card.
321	      address: null,
322	      addressLabel: "Website",
323	      specs: [h.plan?.name, `${Math.round(h.diskQuotaMB / 1024)} GB disk`].filter(Boolean).join(" • ") || null,
324	      status: st.status,
325	      statusLabel: st.label,
326	      location: geo?.city ? { label: geo.city, country: (geo.country ?? "").toLowerCase() } : null,
327	      renewalIso: h.expiresAt ? h.expiresAt.toISOString() : null,
