+ * `chargeHostingRenewal` charges exactly this, so anywhere that DISPLAYS a
+ * hosting renewal amount (lib/nx/services.ts's "My Services" list) must call
+ * this too rather than re-deriving it — a second copy of this formula is how
+ * `plan.priceCents` (the raw monthly list price, ignoring the annual discount
+ * and extra disk) ended up on a customer-facing screen before.
+ */
+export function hostingRenewalPrice(
+  acct: { termMonths?: number | null; annualDiscountPct?: number | null; extraDiskGB?: number | null; plan: { priceCents: number } },
+  liveAnnual: number,
+  perGbCents: number,
+): number {
+  const months = subscriptionTermMonths(acct);
+  const annual = frozenProductAnnualPct(acct) ?? liveAnnual;
+  return productTermRenewalCents(acct.plan.priceCents, months, annual) + extraDiskCentsAt(acct.extraDiskGB ?? 0, perGbCents) * months;
